/// Stack two vectors vertically into a 2-row matrix.
/// Assumes `a` and `b` have the same length.
pub fn vstack(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    debug_assert_eq!(a.len(), b.len(), "vstack requires equal lengths");

    let mut result = Vec::with_capacity(2);
    result.push(a);
    result.push(b);
    result
}

/// Compute the outer product of two vectors:
/// result[i][j] = a[i] * b[j].
pub fn make_outer(a: Vec<f32>, b: Vec<f32>) -> Vec<Vec<f32>> {
    let n = b.len();
    let mut result = Vec::with_capacity(a.len());

    for &ai in &a {
        let mut row = Vec::with_capacity(n);
        for &bj in &b {
            row.push(ai * bj);
        }
        result.push(row);
    }

    result
}

